#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/go/tasks/setup-deps-go.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Download the Go modules, then report the outdated ones, and with audit = \"govulncheck\" the vulnerable ones; --upgrade upgrades them"
# MISE hide=true
# MISE tools={uv="latest", python="3.14"}
# USAGE flag "--upgrade" help="upgrade the dependencies to their latest minor and patch versions instead of downloading the versions of go.sum"

import os
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402


def run(*args, cwd):
  """Run the mise tool args in cwd. A failure stops the task with its code."""
  result = helpers.tool(*args, cwd=cwd)
  if result.returncode != 0:
    sys.exit(result.returncode)


# Shipped with the go tool. Without go or without a go.mod, this is not a Go
# project, so the task does not apply and prints nothing.
if not helpers.has_tool("go"):
  sys.exit(0)
os.chdir(os.environ["MISE_PROJECT_ROOT"])
# A failed git stops the task, with the error of git.
result = subprocess.run(
  [
    "git",
    "-c",
    "core.quotePath=off",
    "ls-files",
    "--cached",
    "--others",
    "--exclude-standard",
    "--",
    "go.mod",
    "*/go.mod",
  ],
  check=False,
  stdout=subprocess.PIPE,
  text=True,
  errors="surrogateescape",
)
if result.returncode != 0:
  sys.exit(result.returncode)
listed = sorted({line for line in result.stdout.split("\n") if line})
if not listed:
  sys.exit(0)
modules = [os.path.dirname(file) or "." for file in listed]
upgrade = os.environ.get("usage_upgrade") == "true"

if upgrade:
  helpers.print_header("Upgrading Go dependencies ...")
else:
  helpers.print_header("Downloading Go dependencies ...")

for folder in modules:
  helpers.print_subheader(f"Preparing the module in {folder} ...")
  if upgrade:
    # -u never changes a major version, because the major version is part of
    # the module path. Thus an upgrade stays inside the versions that the code
    # can import. tidy then removes the modules that are no longer needed.
    run("go", "get", "-u", "./...", cwd=folder)
    run("go", "mod", "tidy", cwd=folder)
  else:
    # go.sum decides the versions; a download never changes it. verify makes
    # sure that each module in the cache matches its hash.
    run("go", "mod", "download", cwd=folder)
    run("go", "mod", "verify", cwd=folder)

for folder in modules:
  helpers.print_subheader(f"Checking for outdated Go dependencies in {folder} ...")
  # A report only: each dependency that has a newer version.
  run(
    "go",
    "list",
    "-m",
    "-u",
    "-f",
    "{{if and (not .Main) (not .Indirect) .Update}}{{.Path}} {{.Version}} -> {{.Update.Version}}{{end}}",
    "all",
    cwd=folder,
  )

# The audit of the dependencies: `audit` of [tools.go]. With "osv-scanner" (the
# default), code:sec:30-osv-scanner scans go.mod with the call analysis of
# govulncheck, and this task does no audit. With "govulncheck", it audits here
# too.
audit = helpers.bootstrap_get("tools.go.audit")["value"]
if audit == "osv-scanner":
  sys.exit(0)
if audit != "govulncheck":
  helpers.print_error(f"[tools.go] audit is {audit!r}, but it must be osv-scanner or govulncheck.")
  sys.exit(2)

# The sync installs govulncheck only when it finds a go.mod. Before the first
# sync after that, it can be missing.
if not helpers.has_tool("govulncheck"):
  helpers.print_warn("govulncheck is not installed - run mise run setup:configs, then mise install")
  sys.exit(0)
for folder in modules:
  helpers.print_subheader(f"Auditing Go dependencies in {folder} for known vulnerabilities ...")
  # Exits 3 when the code calls a vulnerable function, and that stops the setup.
  run("govulncheck", "./...", cwd=folder)
